RSpec.describe "timekeeping:alerts event history reads" do
  def event_history_alert_run(base_url, service_token)
    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    task = Rake::Task["timekeeping:alerts"]
    task.reenable
    output = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = output
      with_timekeeping_env("TIMEKEEPING_BASE_URL" => base_url, "TIMEKEEPING_SERVICE_TOKEN" => service_token) do
        task.invoke
      end
    ensure
      $stdout = original_stdout
    end
    output.string
  end

  # "Add units that gather the required real signals and prove the command reports them."
  # The command only reads the event history: a second run inside the lookback window sees the
  # same change, and the rows other readers of the history rely on are not consumed.
  it "reports the same financial_snapshot_change alert on two runs and leaves the stored events in place" do
    TimekeepingOwnership.ensure_initial!
    company = create(:company)
    Timekeeping::FinancialSnapshot.report([
      Timekeeping::FinancialSnapshot::Difference.new(
        company_id: company.id, kind: :invoice, record_id: 9, field: :discount, old_value: nil, new_value: nil
      )
    ])
    stored = RailsEventViewer::Entry.where(name: "Timekeeping::FinancialSnapshotChanged")
    stored_ids = stored.pluck(:id)
    expect(stored_ids.size).to eq(1)

    base_url = "http://timekeeping.event-history.test"
    service_token = "service-#{SecureRandom.hex(16)}"
    stub_request(:get, "#{base_url}/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{service_token}" })
      .to_return(status: 200, headers: { "Content-Type" => "application/json" }, body: {
        "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
        "companies" => [], "outbox_lag" => []
      }.to_json)

    first = event_history_alert_run(base_url, service_token).lines.grep(/financial_snapshot_change/).grep(/company_id=#{company.id}\b/)
    second = event_history_alert_run(base_url, service_token).lines.grep(/financial_snapshot_change/).grep(/company_id=#{company.id}\b/)

    expect(first.size).to eq(1)
    expect(second).to eq(first)
    expect(stored.pluck(:id)).to eq(stored_ids)
  end
end

RSpec.describe "timekeeping:alerts financial snapshot changes per company" do
  let(:snapshot_tenant_token) { "service-#{SecureRandom.hex(24)}" }

  def run_alerts_for_snapshot_tenants
    TimekeepingOwnership.ensure_initial!
    metrics = {
      "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable", "companies" => [], "outbox_lag" => []
    }
    stub_request(:get, "http://timekeeping.snapshot-tenants.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{snapshot_tenant_token}" })
      .to_return(status: 200, body: JSON.generate(metrics), headers: { "Content-Type" => "application/json" })
    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    Rake::Task["timekeeping:alerts"].reenable
    printed = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = printed
      with_timekeeping_env("TIMEKEEPING_BASE_URL" => "http://timekeeping.snapshot-tenants.test",
                           "TIMEKEEPING_SERVICE_TOKEN" => snapshot_tenant_token) do
        Rake::Task["timekeeping:alerts"].invoke
      end
    rescue SystemExit
      nil
    ensure
      $stdout = original_stdout
    end
    printed.string.lines
  end

  it "prints a financial_snapshot_change alert only under the company whose snapshot changed" do
    changed = create(:company)
    untouched = create(:company)
    Timekeeping::FinancialSnapshot.report([
      Timekeeping::FinancialSnapshot::Difference.new(
        company_id: changed.id, kind: :invoice, record_id: 1, field: :amount, old_value: nil, new_value: nil
      )
    ])

    lines = run_alerts_for_snapshot_tenants.grep(/financial_snapshot_change/).reject { |line| line.match?(/unavailable/i) }

    # Section 11.3: "any change in the financial snapshot pages at once". The alert names the company
    # whose money changed, and never another company that had no change.
    expect(lines.count { |line| line.include?("company_id=#{changed.id}") }).to eq(1)
    expect(lines.none? { |line| line.include?("company_id=#{untouched.id}") }).to be(true)
  end
end

