RSpec.describe "timekeeping:alerts prepare refusals", committed_data: true do
  def refusal_alert_outcome(state, conflicts: [])
    Invoices::ReservationOutcome.new(state:, conflicts:, counts: {})
  end

  def refusal_alert_request(invoice)
    Invoices::ReservationRequest.new(
      company_id: invoice.company_id, invoice_id: invoice.id, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [501]
    )
  end

  def refusal_alert_adapter(reason)
    RecordingReservationAdapter.new(
      prepare: refusal_alert_outcome("refused", conflicts: [{ entry_id: 501, reason: }]),
      commit: refusal_alert_outcome("committed"), abort: refusal_alert_outcome("aborted")
    )
  end

  def refusal_alert_task_output
    base_url = "http://timekeeping.refusal-alerts.test"
    service_token = "service-#{SecureRandom.hex(16)}"
    stub_request(:get, "#{base_url}/internal/v1/metrics").to_return(
      status: 200, headers: { "Content-Type" => "application/json" },
      body: { "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
              "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
              "companies" => [], "outbox_lag" => [] }.to_json
    )
    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    task = Rake::Task["timekeeping:alerts"]
    task.reenable
    output = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = output
      with_timekeeping_env("TIMEKEEPING_BASE_URL" => base_url, "TIMEKEEPING_SERVICE_TOKEN" => service_token) do
        task.invoke
      end
    ensure
      $stdout = original_stdout
    end
    output.string
  end

  it "prints a prepare_refusal alert when the caller rescues an on_another_invoice refusal and commits" do
    TimekeepingOwnership.ensure_initial!
    invoice = create(:invoice)
    request = refusal_alert_request(invoice)

    # The refusal happened when prepare answered, so it must be recorded even though the caller commits.
    ApplicationRecord.transaction do
      Invoices::OperationCoordinator.new(reservations: refusal_alert_adapter("on_another_invoice"))
                                    .call(request, holding: { entry_ids: [501], disposition: "active" })
    rescue Invoices::OperationErrors::Refused
      nil
    end

    alert_lines = refusal_alert_task_output.lines.grep(/prepare_refusal/).grep(/company_id=/)
    expect(alert_lines.grep(/company_id=#{invoice.company_id}\b/).size).to eq(1)
  end
end

