    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    Rake::Task["timekeeping:alerts"].reenable
    output = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = output
      with_timekeeping_env("TIMEKEEPING_BASE_URL" => "http://timekeeping.recon-lookback.test",
                           "TIMEKEEPING_SERVICE_TOKEN" => recon_lookback_token) do
        travel_to(now) { Rake::Task["timekeeping:alerts"].invoke }
      end
    rescue SystemExit
      nil
    ensure
      $stdout = original_stdout
    end
    output.string.lines
