  it "counts a reported unexplained reconciliation difference just inside SIGNAL_LOOKBACK and not one just outside it" do
    TimekeepingOwnership.ensure_initial!
    now = Time.utc(2026, 3, 3, 12, 7)
    lookback = Timekeeping::AlertSignals::SIGNAL_LOOKBACK
    inside = create(:company)
    outside = create(:company)
    travel_to(now - lookback - 1.second) { report_recon_lookback_difference(outside.id) }
    travel_to(now - lookback + 1.second) { report_recon_lookback_difference(inside.id) }

    alert_lines = run_alerts_for_recon_lookback(now).grep(/reconciliation_difference/).grep(/company_id=\d+/)

    # "Add units that gather the required real signals and prove the command reports them."
    expect(alert_lines.count { |line| line.include?("company_id=#{inside.id}") }).to eq(1)
    expect(alert_lines.none? { |line| line.include?("company_id=#{outside.id}") }).to be(true)
  end
end

RSpec.describe "timekeeping:alerts ownership_moving delivery blocker" do
  include ActiveSupport::Testing::TimeHelpers

  let(:blocker_token) { "service-#{SecureRandom.hex(24)}" }

  it "prints ownership_moving as the only sourceless signal unavailable line and exits zero" do
    TimekeepingOwnership.ensure_initial!
    stub_request(:get, "http://timekeeping.blocker.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{blocker_token}" })
      .to_return(status: 200, headers: { "Content-Type" => "application/json" }, body: {
        "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
        "companies" => [], "outbox_lag" => []
      }.to_json)
    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    Rake::Task["timekeeping:alerts"].reenable
    output = StringIO.new
    original_stdout = $stdout
    exit_status = 0
    begin
      $stdout = output
      with_timekeeping_env("TIMEKEEPING_BASE_URL" => "http://timekeeping.blocker.test",
                           "TIMEKEEPING_SERVICE_TOKEN" => blocker_token) do
        travel_to(Time.utc(2026, 3, 3, 12, 7)) { Rake::Task["timekeeping:alerts"].invoke }
      end
    rescue SystemExit => e
      exit_status = e.status
    ensure
      $stdout = original_stdout
    end
    unavailable_lines = output.string.lines.grep(/unavailable/i)

    # "Where an upstream source truly does not exist, identify that dependency as a delivery blocker
    # rather than declaring all requirements complete."
    # Nothing records when an ownership pause starts or how long it is planned to last, so it stays unavailable.
    expect(unavailable_lines.count { |line| line.include?("ownership_moving") }).to eq(1)
    # The three signals that now have a real source must not be reported as unavailable.
    %w[prepare_refusal reconciliation_difference financial_snapshot_change].each do |name|
      expect(unavailable_lines.none? { |line| line.include?(name) }).to be(true), "#{name} still printed unavailable"
    end
    expect(exit_status).to eq(0)
  end
end

RSpec.describe "timekeeping:alerts with an unreadable event history" do
  it "prints unavailable lines, not silence, for event-history signals when the event history cannot be read, and still prints the stale_generation alert" do
    TimekeepingOwnership.ensure_initial!
    company = create(:company)
    TimekeepingStaleGenerationRefusal.create!(company_id: company.id, handoff_step: nil)

    base_url = "http://timekeeping.unreadable-history.test"
    service_token = "service-#{SecureRandom.hex(16)}"
    stub_request(:get, "#{base_url}/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{service_token}" })
      .to_return(status: 200, headers: { "Content-Type" => "application/json" }, body: {
        "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
        "companies" => [], "outbox_lag" => []
      }.to_json)

    # A broken event-history read must never look like a healthy zero.
    allow(RailsEventViewer::Entry).to receive(:where).and_raise(ActiveRecord::StatementInvalid, "relation missing")

    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    task = Rake::Task["timekeeping:alerts"]
    task.reenable
    output = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = output
      with_timekeeping_env("TIMEKEEPING_BASE_URL" => base_url, "TIMEKEEPING_SERVICE_TOKEN" => service_token) do
        task.invoke
      rescue SystemExit
        nil
      end
    ensure
      $stdout = original_stdout
    end
    lines = output.string.lines

    # "Printing unavailable is honest, but it does not deliver the requested local alerts."
    %w[reconciliation_difference financial_snapshot_change].each do |signal|
      expect(lines.count { |line| line.include?(signal) && line.match?(/unavailable/i) }).to eq(1)
      expect(lines.none? { |line| line.include?(signal) && line.include?("company_id=") }).to be(true)
    end
    # One failed read must not stop the command from reporting the other signals.
    expect(lines.count { |line| line.include?("stale_generation") && line.include?("company_id=#{company.id}") }).to eq(1)
  end
end
